import { ErrorBoundaryFallbackProps } from '@suspensive/react';
import { EmptyList } from '~/widgets/empty-list';
import { parseError } from '~/shared/lib/utils/error-message';

type FallbackErrorMessageProps = {
  showReset?: boolean;
  type?: FallbackErrorMessageType;
} & ErrorBoundaryFallbackProps<any>;

export enum FallbackErrorMessageType {
  Empty = 'empty',
  Alert = 'alert',
  Error = 'error',
}

export const FallbackErrorMessage = ({
  error,
  reset,
  showReset = true,
  type = FallbackErrorMessageType.Alert,
}: FallbackErrorMessageProps) => {
  const parsedError = parseError(error);

  return <EmptyList message={parsedError.message} reset={showReset ? reset : undefined} type={type} />;
};
